static std::random_device rd;
static std::mt19937 e2(rd());
assert(numberOfChecks % 2 == 1);
int inside = 0;
std::uniform_real_distribution<> dist(0, 6);
std::uniform_real_distribution<> distx(bb.minX(), bb.maxX());
std::uniform_real_distribution<> disty(bb.minY(), bb.maxY());
std::uniform_real_distribution<> distz(bb.minZ(), bb.maxZ());
for (int i = 0; i < numberOfChecks; i++) {
    Point3d boundingPoint;
    double n1, n2;
    int side = std::floor(dist(e2));
    switch(side % 3){
        case 0: // x
            n1 = disty(e2);
            n2 = distz(e2);
            boundingPoint.setY(n1);
            boundingPoint.setZ(n2);
            if (side == 0) boundingPoint.setX(bb.minX());
            else boundingPoint.setX(bb.maxX());
            break;
        case 1: // y
            n1 = distx(e2);
            n2 = distz(e2);
            boundingPoint.setX(n1);
            boundingPoint.setZ(n2);
            if (side == 1) boundingPoint.setY(bb.minY());
            else boundingPoint.setY(bb.maxY());
            break;
        case 2: // z
            n1 = distx(e2);
            n2 = disty(e2);
            boundingPoint.setX(n1);
            boundingPoint.setY(n2);
            if (side == 2) boundingPoint.setZ(bb.minZ());
            else boundingPoint.setZ(bb.maxZ());
            break;
    }
    CGALRay ray(p, boundingPoint);
    if (tree.number_of_intersected_primitives(ray) % 2 == 1) inside++;
}
return inside > numberOfChecks / 2;

